#include <vector>

using namespace std;

class ModifiedBinarySearchTemplate {
public:
    // Order-Agnostic Binary Search template
    int search(const vector<int>& arr, int key) {
        int start = 0;
        int end = arr.size() - 1;

        if (arr.empty()) return -1;

        // Detect sort order
        bool isAscending = arr[start] < arr[end];

        while (start <= end) {
            int mid = start + (end - start) / 2; // Prevents overflow

            if (arr[mid] == key) {
                return mid;
            }

            if (isAscending) {
                if (key < arr[mid]) {
                    end = mid - 1;
                } else {
                    start = mid + 1;
                }
            } else { // Descending
                if (key > arr[mid]) {
                    end = mid - 1;
                } else {
                    start = mid + 1;
                }
            }
        }
        return -1; // Target not found
    }
};

